接口名称：startFileUpload
接口描述：初始化分片上传，可选择前端直传 OSS/COS。
分组：文件管理
网关分发指令：command=11001 (CommandId.StartFileChunkUpload)
代码来源：src/api/file/index.ts
Req:
{
  "entryPoint": 1,
  "fileName": "model.stl",
  "fileSize": 1024,
  "md5": "file-md5",
  "frontendOssUpload": true,
  "partsInfo": [
    {
      "partID": 1,
      "partMD5": "part-md5",
      "partSize": 1024
    }
  ],
  "extra": {
    "files": [
      {
        "filename": "model.stl",
        "offset": 0,
        "length": 1024
      }
    ],
    "compressVersion": 0,
    "cryptoVersion": 0
  },
  "parentKey": "parent-file-key"
}
Res:
{
  "code": 0,
  "data": {
    "fileKey": "file-key",
    "frontendOssUploadPartsInfo": [
      {
        "partID": 1,
        "fileKey": "oss-key"
      }
    ],
    "ossAuthInfo": {
      "accessKey": "access-key",
      "accessSecret": "access-secret",
      "securityToken": "security-token",
      "bucketName": "bucket",
      "endpoint": "endpoint",
      "provider": 1,
      "region": "region"
    }
  },
  "message": "success"
}

